def _scale(fmt, v):
    """Return (value, unit) applying the gem's display scaling to a raw int."""
    signed = v - 65536 if v >= 32768 else v
    if "0.1f" in fmt:
        unit = fmt.split("f", 1)[1].strip()
        return round(signed / 10.0, 1), unit
    if fmt.startswith("%d"):
        return signed, fmt[2:].strip()
    return v, ""  # unknown/bitfield: expose the raw value


def build_extra(raw_registers, exclude=()):
    """Decode every gem-known raw register into {name: {register, raw, value, unit}}.

    Skips 0xFFFF ("absent") readings and any register id in ``exclude`` (the ones
    the primary record already handles), so this section is purely the new data.
    """
    out = {}
    for reg_id, raw in raw_registers.items():
        if reg_id in exclude or reg_id not in REG_INFO:
            continue
        if not isinstance(raw, int) or raw == ABSENT:
            continue
        name, fmt = REG_INFO[reg_id]
        value, unit = _scale(fmt, raw)
        entry = {"register": int(reg_id), "raw": raw, "value": value}
        if unit:
            entry["unit"] = unit
        out[name] = entry
    return out
